import collections, sys
from unittest import mock
sys.path.insert(0, sys.argv[1])
import oracles, runner
from suite import CASES, MUTANTS

def campaign():
    counts = collections.Counter()
    for case in CASES:
        base = runner.run_variant(case, "baseline")
        counts[base["status"]] += 1
        for m in MUTANTS[case["model"]]:
            counts[runner.run_variant(case, m, baseline_status=base["status"])["status"]] += 1
    return dict(counts)

print("oráculo real:", campaign())
with mock.patch.object(oracles, "evaluate", lambda case, n: [float("nan")] * 4):
    print("oráculo NaN: ", campaign())
